for cat, entries in more_de_entries.items():
    filep = os.path.join(BASE_DIR, "A1", cat)
    with open(filep, "r", encoding="utf-8") as f:
        content = f.read()
    # parse existing JSON data
    import re
    m = re.search(r"const data = (\[[\s\S]*?\]);", content)
    if m:
        arr = json.loads(m.group(1))
        arr.extend(entries)
        write_js(filep, "de", arr)

